import { index, pgTable, text, timestamp, uuid } from 'drizzle-orm/pg-core';

/**
 * An asset as users see it. Its file versions live in `asset_versions`, its tags in
 * `asset_tags`; the current version is the one with the highest number (no
 * back-reference column, which would create a circular foreign key).
 */
export const assets = pgTable(
  'assets',
  {
    /** UUIDv7 generated by the service before INSERT (ADR 003). */
    id: uuid().primaryKey(),
    title: text().notNull(),
    createdAt: timestamp({ withTimezone: true }).notNull().defaultNow(),
    updatedAt: timestamp({ withTimezone: true }).notNull().defaultNow(),
  },
  (table) => [
    /**
     * Keyset pagination for ListAssets: `WHERE (created_at, id) < ($1, $2) ORDER BY created_at DESC, id DESC`.
     * NULLS FIRST matches Postgres' default for DESC; with a different NULLS order the planner
     * can't use the index for ORDER BY (even on NOT NULL columns) and sorts in memory instead.
     */
    index('assets_created_at_id_idx').on(
      table.createdAt.desc().nullsFirst(),
      table.id.desc().nullsFirst(),
    ),
  ],
);
